examples:
两个重载的核心形式：
```cpp
template <typename T1, typename T2>
std::enable_if_t<std::is_same_v<T1, T2>, bool>
checkType(const T1& t1, const T2& t2) {
    return true;
}

template <typename T1, typename T2>
std::enable_if_t<!std::is_same_v<T1, T2>, bool>
checkType(const T1& t1, const T2& t2) {
    return false;
}
```
